    iIntros "#Ht".
    uis_rvc2 g 0xd3a (mword_of_int 0x4605 : mword 16) udec_4605.
  Qed.

  (* 0xd3c  addi a1,s0,-17  (base, 4-aligned) *)
  Lemma uis_shk_d3c (g : gname) :
    shk_code g -∗
    uinstr_is g (mword_of_int 0xd3c) false
      (ITYPE (mword_of_int 4079 : mword 12, Regidx (mword_of_int 8), Regidx (mword_of_int 11), ADDI)).
  Proof.
    iIntros "#Ht".
    uis_base g 0xd3c (mword_of_int 0xfef40593 : mword 32) udec_fef40593.
  Qed.

  (* 0xd40  jal ca6 <write>  (base, 4-aligned) *)
  Lemma uis_shk_d40 (g : gname) :
    shk_code g -∗
    uinstr_is g (mword_of_int 0xd40) false
      (JAL (mword_of_int 2096998 : mword 21, Regidx (mword_of_int 1))).
  Proof.
    iIntros "#Ht".
    uis_base g 0xd40 (mword_of_int 0xf67ff0ef : mword 32) udec_f67ff0ef.
  Qed.

  (* 0xd44  c.ldsp ra,24(sp)  (RVC, 4-aligned) *)
  Lemma uis_shk_d44 (g : gname) :
    shk_code g -∗
    uinstr_is g (mword_of_int 0xd44) true
      (C_LDSP (mword_of_int 3 : mword 6, Regidx (mword_of_int 1))).
  Proof.
    iIntros "#Ht".
    uis_rvc4 g 0xd44 (mword_of_int 0x60e2 : mword 16) udec_60e2
      (mword_of_int 0x644260e2 : mword 32).
  Qed.

  (* 0xd46  c.ldsp s0,16(sp)  (RVC, 2 mod 4) *)
  Lemma uis_shk_d46 (g : gname) :
    shk_code g -∗
    uinstr_is g (mword_of_int 0xd46) true
      (C_LDSP (mword_of_int 2 : mword 6, Regidx (mword_of_int 8))).
  Proof.
    iIntros "#Ht".
    uis_rvc2 g 0xd46 (mword_of_int 0x6442 : mword 16) udec_6442.
  Qed.

  (* 0xd48  c.addi16sp sp,sp,32  (RVC, 4-aligned) *)
  Lemma uis_shk_d48 (g : gname) :
    shk_code g -∗
    uinstr_is g (mword_of_int 0xd48) true
      (C_ADDI16SP (mword_of_int 2 : mword 6)).
  Proof.
    iIntros "#Ht".
    uis_rvc4 g 0xd48 (mword_of_int 0x6105 : mword 16) udec_6105
      (mword_of_int 0x80826105 : mword 32).
  Qed.

  (* 0xd4a  c.jr  (RVC, 2 mod 4) *)
  Lemma uis_shk_d4a (g : gname) :
    shk_code g -∗
    uinstr_is g (mword_of_int 0xd4a) true
      (C_JR (Regidx (mword_of_int 1))).
  Proof.
    iIntros "#Ht".
    uis_rvc2 g 0xd4a (mword_of_int 0x8082 : mword 16) udec_8082.
  Qed.

  (* =================================================================== *)
  (* §3 Where the catalog comes from.                                      *)
  (* =================================================================== *)

  (* [shk_code] is defined above, at the top of the section, because every
     per-pc lemma consumes it. This is its INTRODUCTION, and the ONE place in
     the whole development where the program's bytes meet the process image:
     the entry hands out [utext_all gt M pm] -- the text half of the heap,
     over the image the kernel actually loaded -- and the two section
     hypotheses say that image contains the dump ([shk_text_sub]) and that
     the executable segment is X-and-not-W ([Hx]), which is what puts those
     bytes in the TEXT half rather than the data one. Both are discharged
     HERE, once, instead of in each of the 615 per-pc lemmas. *)

  (* AND THE READ-ONLY IMAGE BESIDE IT. A program's string LITERALS are not
     in [ShInstrs.sh_bytes] and they are not in the data half either: .rodata
     shares the EXECUTABLE segment's pages, so its bytes are X-and-not-W and
     the heap files them under [γt] exactly as it files the code. init's four
     format strings sit at 0x970..0x9e7, inside the R-X segment, and vprintf
     LOADS them one byte at a time. This is the part of [ShData.sh_data] that
     lands there -- everything below the end of the executable segment -- and
     [UserHeap.utext_str_of_img] cuts a literal out of it at a concrete base
     and length. *)
  Definition shk_ro : gmap Z (bv 8) :=
    filter (fun kv => (kv.1 < 8192)%Z) ShData.sh_data.

  Definition shk_rodata (g : gname) : iProp Σ := utext_img g shk_ro.

  Global Instance shk_rodata_persistent g : Persistent (shk_rodata g).
  Proof. apply _. Qed.

  Global Typeclasses Opaque shk_rodata.

  Lemma shk_rodata_of_text : utext_all gt M pm -∗ shk_rodata gt.
  Proof.
    assert (Hin : forall (a : Z) (b : bv 8),
               shk_ro !! a = Some b -> M !! a = Some b).
    { intros a b Hb. apply map_lookup_filter_Some in Hb as [Hb _].
      exact (Hsub2 a b Hb). }
    assert (Hp : forall a : Z, is_Some (shk_ro !! a) ->
                   ux_addr pm a /\ ~ uw_addr pm a).
    { intros a [b Hb]. apply map_lookup_filter_Some in Hb as [Hb Hlt].
      apply Hx.
      pose proof (shk_data_key_nonneg a b Hb) as Hge.
      simpl in Hlt. lia. }
    iIntros "#Ht". rewrite /shk_rodata.
    iApply (utext_img_of_all gt M pm shk_ro Hin Hp with "Ht").
  Qed.

  Lemma shk_code_of_text : utext_all gt M pm -∗ shk_code gt.
  Proof.
    assert (Hin : forall (a : Z) (b : bv 8),
               ShInstrs.sh_bytes !! a = Some b -> M !! a = Some b)
      by exact Hsub.
    assert (Hp : forall a : Z, is_Some (ShInstrs.sh_bytes !! a) ->
                   ux_addr pm a /\ ~ uw_addr pm a).
    { intros a [b Hb]. apply Hx.
      pose proof (shk_bytes_key_lt a b Hb) as Hlt.
      pose proof (shk_bytes_key_nonneg a b Hb) as Hge. lia. }
    iIntros "#Ht". rewrite /shk_code.
    iApply (utext_img_of_all gt M pm ShInstrs.sh_bytes Hin Hp with "Ht").
  Qed.

End UCodeShK.
